use flate2::read::MultiGzDecoder;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read, Write};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Format {
    Fasta,
    Fastq,
}

#[derive(Clone, Debug)]
pub struct Record {
    pub name: String,
    pub comment: Option<String>,
    pub seq: Vec<u8>,
    pub qual: Option<Vec<u8>>,
}

impl Record {
    pub fn len(&self) -> usize {
        self.seq.len()
    }

    pub fn is_fastq(&self) -> bool {
        self.qual.is_some()
    }
}

pub fn read_fastx(path: Option<&str>) -> Result<(Vec<Record>, Option<Format>), String> {
    let mut reader = open_reader(path).map_err(|e| open_error(path, e))?;
    load_fastx(&mut *reader)
}

pub fn open_reader(path: Option<&str>) -> io::Result<Box<dyn BufRead>> {
    match path {
        Some(path) if path != "-" => {
            let file = File::open(path)?;
            reader_from(file)
        }
        _ => reader_from(io::stdin()),
    }
}

fn reader_from<R: Read + 'static>(reader: R) -> io::Result<Box<dyn BufRead>> {
    let mut reader = BufReader::new(reader);
    let gz = is_gzip(&mut reader)?;
    if gz {
        Ok(Box::new(BufReader::new(MultiGzDecoder::new(reader))))
    } else {
        Ok(Box::new(reader))
    }
}

fn is_gzip<R: BufRead>(reader: &mut R) -> io::Result<bool> {
    let buf = reader.fill_buf()?;
    Ok(buf.len() >= 2 && buf[0] == 0x1f && buf[1] == 0x8b)
}

fn load_fastx(reader: &mut dyn BufRead) -> Result<(Vec<Record>, Option<Format>), String> {
    let mut first = String::new();
    loop {
        first.clear();
        let n = reader
            .read_line(&mut first)
            .map_err(|e| format!("failed to read input: {e}"))?;
        if n == 0 {
            return Ok((Vec::new(), None));
        }
        if !trim_eol(&first).is_empty() {
            break;
        }
    }
    match first.as_bytes().first().copied() {
        Some(b'>') => parse_fasta(reader, first),
        Some(b'@') => parse_fastq(reader, first),
        _ => Err("failed to detect FASTA/Q format".to_string()),
    }
}

fn parse_fasta(
    reader: &mut dyn BufRead,
    first_header: String,
) -> Result<(Vec<Record>, Option<Format>), String> {
    let mut records = Vec::new();
    let mut pending = Some(first_header);
    let mut line = String::new();
    while let Some(header) = pending.take() {
        let (name, comment) = split_header(trim_eol(&header), '>');
        let mut seq = Vec::new();
        loop {
            line.clear();
            let n = reader
                .read_line(&mut line)
                .map_err(|e| format!("failed to read FASTA: {e}"))?;
            if n == 0 {
                break;
            }
            let stripped = trim_eol(&line);
            if stripped.starts_with('>') {
                pending = Some(line.clone());
                break;
            }
            if stripped.is_empty() {
                continue;
            }
            seq.extend_from_slice(stripped.as_bytes());
        }
        records.push(Record {
            name,
            comment,
            seq,
            qual: None,
        });
    }
    Ok((records, Some(Format::Fasta)))
}

fn parse_fastq(
    reader: &mut dyn BufRead,
    first_header: String,
) -> Result<(Vec<Record>, Option<Format>), String> {
    let mut records = Vec::new();
    let mut pending = Some(first_header);
    let mut line = String::new();
    while let Some(header) = pending.take() {
        let (name, comment) = split_header(trim_eol(&header), '@');
        let mut seq = Vec::new();
        loop {
            line.clear();
            let n = reader
                .read_line(&mut line)
                .map_err(|e| format!("failed to read FASTQ: {e}"))?;
            if n == 0 {
                return Err("truncated FASTQ sequence".to_string());
            }
            let stripped = trim_eol(&line);
            if stripped.starts_with('+') {
                break;
            }
            seq.extend_from_slice(stripped.as_bytes());
        }
        let mut qual = Vec::new();
        while qual.len() < seq.len() {
            line.clear();
            let n = reader
                .read_line(&mut line)
                .map_err(|e| format!("failed to read FASTQ quality: {e}"))?;
            if n == 0 {
                break;
            }
            qual.extend_from_slice(trim_eol(&line).as_bytes());
        }
        if qual.len() > seq.len() {
            qual.truncate(seq.len());
        }
        records.push(Record {
            name,
            comment,
            seq,
            qual: Some(qual),
        });

        loop {
            line.clear();
            let n = reader
                .read_line(&mut line)
                .map_err(|e| format!("failed to read FASTQ header: {e}"))?;
            if n == 0 {
                return Ok((records, Some(Format::Fastq)));
            }
            if trim_eol(&line).is_empty() {
                continue;
            }
            pending = Some(line.clone());
            break;
        }
    }
    Ok((records, Some(Format::Fastq)))
}

fn split_header(header: &str, prefix: char) -> (String, Option<String>) {
    let rest = header.strip_prefix(prefix).unwrap_or(header);
    let mut split_at = None;
    for (idx, ch) in rest.char_indices() {
        if ch.is_whitespace() {
            split_at = Some(idx);
            break;
        }
    }
    match split_at {
        Some(idx) => {
            let name = rest[..idx].to_string();
            let comment = rest[idx..].trim_start().to_string();
            if comment.is_empty() {
                (name, None)
            } else {
                (name, Some(comment))
            }
        }
        None => (rest.to_string(), None),
    }
}

pub fn trim_eol(s: &str) -> &str {
    s.trim_end_matches(['\r', '\n'])
}

pub fn write_record<W: Write>(
    writer: &mut W,
    record: &Record,
    format: Format,
    line_len: usize,
    comment_override: Option<&str>,
) -> io::Result<()> {
    let prefix = match format {
        Format::Fasta => '>',
        Format::Fastq => '@',
    };
    write!(writer, "{prefix}{}", record.name)?;
    match comment_override {
        Some(comment) if !comment.is_empty() => write!(writer, " {comment}")?,
        None => {
            if let Some(comment) = record.comment.as_deref() {
                if !comment.is_empty() {
                    write!(writer, " {comment}")?;
                }
            }
        }
        _ => {}
    }
    writer.write_all(b"\n")?;
    write_wrapped(writer, &record.seq, line_len)?;
    if format == Format::Fastq {
        writer.write_all(b"+\n")?;
        let qual = record.qual.as_deref().unwrap_or(&[]);
        write_wrapped(writer, qual, line_len)?;
    }
    Ok(())
}

pub fn write_record_with_header<W: Write>(
    writer: &mut W,
    header_prefix: char,
    name: &str,
    comment: Option<&str>,
    seq: &[u8],
    qual: Option<&[u8]>,
    line_len: usize,
) -> io::Result<()> {
    write!(writer, "{header_prefix}{name}")?;
    if let Some(comment) = comment {
        if !comment.is_empty() {
            write!(writer, " {comment}")?;
        }
    }
    writer.write_all(b"\n")?;
    write_wrapped(writer, seq, line_len)?;
    if let Some(qual) = qual {
        writer.write_all(b"+\n")?;
        write_wrapped(writer, qual, line_len)?;
    }
    Ok(())
}

pub fn write_wrapped<W: Write>(writer: &mut W, text: &[u8], line_len: usize) -> io::Result<()> {
    if line_len == 0 || text.is_empty() {
        writer.write_all(text)?;
        writer.write_all(b"\n")?;
        return Ok(());
    }
    for chunk in text.chunks(line_len) {
        writer.write_all(chunk)?;
        writer.write_all(b"\n")?;
    }
    Ok(())
}

pub fn open_error(path: Option<&str>, error: io::Error) -> String {
    match path {
        Some(_) => format!("failed to open the input file/stream: {error}"),
        None => format!("failed to open the input file/stream: {error}"),
    }
}

pub fn complement_base(base: u8) -> u8 {
    let lower = base.to_ascii_lowercase();
    let comp = match lower {
        b'a' => b't',
        b'c' => b'g',
        b'g' => b'c',
        b't' | b'u' => b'a',
        b'r' => b'y',
        b'y' => b'r',
        b'k' => b'm',
        b'm' => b'k',
        b's' => b's',
        b'w' => b'w',
        b'b' => b'v',
        b'd' => b'h',
        b'h' => b'd',
        b'v' => b'b',
        b'x' => b'x',
        _ => b'n',
    };
    if base.is_ascii_lowercase() {
        comp
    } else {
        comp.to_ascii_uppercase()
    }
}

pub fn reverse_complement(seq: &[u8]) -> Vec<u8> {
    seq.iter().rev().map(|&b| complement_base(b)).collect()
}

pub fn upper_seq(seq: &mut [u8]) {
    for base in seq {
        *base = base.to_ascii_uppercase();
    }
}

pub fn lower_base(base: u8) -> u8 {
    base.to_ascii_lowercase()
}

pub fn mask_char(base: u8, ch: u8) -> u8 {
    match ch {
        b'X' => base.to_ascii_uppercase(),
        b'x' => base.to_ascii_lowercase(),
        other => other,
    }
}

pub fn is_n(base: u8) -> bool {
    matches!(base.to_ascii_lowercase(), b'n' | b'x')
}

pub fn is_het2(base: u8) -> bool {
    matches!(base.to_ascii_lowercase(), b'r' | b'y' | b'k' | b'm' | b's' | b'w')
}

pub fn het_class(base: u8) -> Option<&'static [u8]> {
    match base.to_ascii_lowercase() {
        b'a' => Some(b"A"),
        b'c' => Some(b"C"),
        b'g' => Some(b"G"),
        b't' | b'u' => Some(b"T"),
        b'r' => Some(b"AG"),
        b'y' => Some(b"CT"),
        b'k' => Some(b"GT"),
        b'm' => Some(b"AC"),
        b's' => Some(b"CG"),
        b'w' => Some(b"AT"),
        b'b' => Some(b"CGT"),
        b'd' => Some(b"AGT"),
        b'h' => Some(b"ACT"),
        b'v' => Some(b"ACG"),
        b'n' | b'x' => Some(b"ACGT"),
        _ => None,
    }
}

pub fn encode_alleles(bits: u8, lower: bool, empty_char: u8) -> u8 {
    let base = match bits {
        0b0001 => b'A',
        0b0010 => b'C',
        0b0100 => b'G',
        0b1000 => b'T',
        0b0101 => b'R',
        0b1010 => b'Y',
        0b1100 => b'K',
        0b0011 => b'M',
        0b0110 => b'S',
        0b1001 => b'W',
        0b1110 => b'B',
        0b1101 => b'D',
        0b1011 => b'H',
        0b0111 => b'V',
        0b1111 => b'N',
        _ => empty_char,
    };
    if lower {
        base.to_ascii_lowercase()
    } else {
        base
    }
}

pub fn allele_bits(base: u8) -> u8 {
    match base.to_ascii_lowercase() {
        b'a' => 0b0001,
        b'c' => 0b0010,
        b'g' => 0b0100,
        b't' | b'u' => 0b1000,
        b'r' => 0b0101,
        b'y' => 0b1010,
        b'k' => 0b1100,
        b'm' => 0b0011,
        b's' => 0b0110,
        b'w' => 0b1001,
        b'b' => 0b1110,
        b'd' => 0b1101,
        b'h' => 0b1011,
        b'v' => 0b0111,
        b'n' | b'x' => 0b1111,
        _ => 0,
    }
}

pub fn record_format(record: &Record) -> Format {
    if record.qual.is_some() {
        Format::Fastq
    } else {
        Format::Fasta
    }
}

