mod fastx;

use fastx::{
    allele_bits, complement_base, encode_alleles, is_het2, is_n, lower_base, mask_char,
    read_fastx, record_format, reverse_complement, upper_seq, write_record,
    write_record_with_header, Format, Record,
};
use std::cmp::{max, min};
use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::env;
use std::fs::{self, File};
use std::io::{self, BufRead, BufReader, BufWriter, Write};
use std::path::Path;
use std::process;

const TOP_LEVEL_USAGE: &str = r#"
Usage:   seqtk <command> <arguments>
Version: 1.5-r133

Command: seq       common transformation of FASTA/Q
         size      report the number sequences and bases
         comp      get the nucleotide composition of FASTA/Q
         sample    subsample sequences
         subseq    extract subsequences from FASTA/Q
         fqchk     fastq QC (base/quality summary)
         mergepe   interleave two PE FASTA/Q files
         split     split one file into multiple smaller files
         trimfq    trim FASTQ using the Phred algorithm

         hety      regional heterozygosity
         gc        identify high- or low-GC regions
         mutfa     point mutate FASTA at specified positions
         mergefa   merge two FASTA/Q files
         famask    apply a X-coded FASTA to a source FASTA
         dropse    drop unpaired from interleaved PE FASTA/Q
         rename    rename sequence names
         randbase  choose a random base from hets
         cutN      cut sequence at long N
         gap       get the gap locations
         listhet   extract the position of each het
         hpc       homopolyer-compressed sequence
         telo      identify telomere repeats in asm or long reads
"#;

const SAMPLE_USAGE: &str = r#"
Usage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>

Options: -s INT       RNG seed [11]
         -2           2-pass mode: twice as slow but with much reduced memory
"#;

const SUBSEQ_USAGE: &str = r#"Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>
Options:
  -t       TAB delimited output
  -s       strand aware
  -l INT   sequence line length [0]
Note: Use 'samtools faidx' if only a few regions are intended.
"#;

const FQCHK_USAGE: &str = r#"Usage: seqtk fqchk [-q 20] <in.fq>
Note: use -q0 to get the distribution of all quality values
"#;

const MERGEPE_USAGE: &str = "Usage: seqtk mergepe <in1.fq> <in2.fq>\n";
const SPLIT_USAGE: &str = r#"Usage: seqtk split [options] <prefix> <in.fa>
Options:
  -n INT    number of files [10]
  -l INT    line length [0]
"#;

const TRIMFQ_USAGE: &str = r#"
Usage:   seqtk trimfq [options] <in.fq>

Options: -q FLOAT    error rate threshold (disabled by -b/-e) [0.05]
         -l INT      maximally trim down to INT bp (disabled by -b/-e) [30]
         -b INT      trim INT bp from left (non-zero to disable -q/-l) [0]
         -e INT      trim INT bp from right (non-zero to disable -q/-l) [0]
         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [0]
         -Q          force FASTQ output
"#;

const HETY_USAGE: &str = r#"
Usage:   seqtk hety [options] <in.fa>

Options: -w INT   window size [50000]
         -t INT   # start positions in a window [5]
         -m       treat lowercases as masked
"#;

const GC_USAGE: &str = r#"Usage: seqtk gc [options] <in.fa>
Options:
  -w         identify high-AT regions
  -f FLOAT   min GC fraction (or AT fraction for -w) [0.60]
  -l INT     min region length to output [20]
  -x FLOAT   X-dropoff [10.0]
"#;

const MUTFA_USAGE: &str = r#"Usage: seqtk mutfa <in.fa> <in.snp>

Note: <in.snp> contains at least four columns per line which are:
      'chr  1-based-pos  any  base-changed-to'.
"#;

const MERGEFA_USAGE: &str = r#"
Usage: seqtk mergefa [options] <in1.fa> <in2.fa>

Options: -q INT   quality threshold [0]
         -i       take intersection
         -m       convert to lowercase when one of the input base is N
         -r       pick a random allele from het
         -h       suppress hets in the input
"#;

const FAMASK_USAGE: &str = "Usage: seqtk famask <src.fa> <mask.fa>\n";
const CUTN_USAGE: &str = r#"
Usage:   seqtk cutN [options] <in.fa>

Options: -n INT    min size of N tract [1000]
         -p INT    penalty for a non-N [10]
         -g        print gaps only, no sequence
"#;
const GAP_USAGE: &str = "Usage: seqtk gap [-l 50] <in.fa>\n";
const LISTHET_USAGE: &str = "Usage: seqtk listhet <in.fa>\n";
const RANDBASE_USAGE: &str = "Usage: seqtk randbase <in.fa>\n";

fn main() {
    process::exit(run());
}

fn run() -> i32 {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        print!("{TOP_LEVEL_USAGE}");
        return 1;
    }
    match args[1].as_str() {
        "seq" => cmd_seq(&args[2..]),
        "size" => cmd_size(&args[2..]),
        "comp" => cmd_comp(&args[2..]),
        "sample" => cmd_sample(&args[2..]),
        "subseq" => cmd_subseq(&args[2..]),
        "fqchk" => cmd_fqchk(&args[2..]),
        "mergepe" => cmd_mergepe(&args[2..]),
        "split" => cmd_split(&args[2..]),
        "trimfq" => cmd_trimfq(&args[2..]),
        "hety" => cmd_hety(&args[2..]),
        "gc" => cmd_gc(&args[2..]),
        "mutfa" => cmd_mutfa(&args[2..]),
        "mergefa" => cmd_mergefa(&args[2..]),
        "famask" => cmd_famask(&args[2..]),
        "dropse" => cmd_dropse(&args[2..]),
        "rename" => cmd_rename(&args[2..]),
        "randbase" => cmd_randbase(&args[2..]),
        "cutN" => cmd_cutn(&args[2..]),
        "gap" => cmd_gap(&args[2..]),
        "listhet" => cmd_listhet(&args[2..]),
        "hpc" => cmd_hpc(&args[2..]),
        "telo" => cmd_telo(&args[2..]),
        other => {
            eprintln!("[main] unrecognized command '{other}'. Abort!");
            1
        }
    }
}

fn read_cmd_input(args: &[String], tag: &str) -> Result<(Vec<Record>, Option<Format>), i32> {
    let path = args.first().map(String::as_str);
    match read_fastx(path) {
        Ok(value) => Ok(value),
        Err(_) => {
            eprintln!("[E::stk_{tag}] failed to open the input file/stream.");
            Err(1)
        }
    }
}

fn cmd_size(args: &[String]) -> i32 {
    let (records, _) = match read_cmd_input(args, "size") {
        Ok(v) => v,
        Err(code) => return code,
    };
    let bases: usize = records.iter().map(Record::len).sum();
    println!("{}\t{}", records.len(), bases);
    0
}

fn cmd_comp(args: &[String]) -> i32 {
    let (records, _) = match read_cmd_input(args, "comp") {
        Ok(v) => v,
        Err(code) => return code,
    };
    let mut out = BufWriter::new(io::stdout().lock());
    for record in records {
        let mut a = 0usize;
        let mut c = 0usize;
        let mut g = 0usize;
        let mut t = 0usize;
        let mut n2 = 0usize;
        let mut n3 = 0usize;
        let mut n4 = 0usize;
        let mut cpg_bases = 0usize;
        let mut tv = 0usize;
        let mut ts = 0usize;
        let mut cpg_ts = 0usize;
        for &base in &record.seq {
            match base.to_ascii_lowercase() {
                b'a' => a += 1,
                b'c' => c += 1,
                b'g' => g += 1,
                b't' | b'u' => t += 1,
                b'r' | b'y' | b'k' | b'm' | b's' | b'w' => {
                    n2 += 1;
                    match base.to_ascii_lowercase() {
                        b'r' | b'y' => ts += 1,
                        _ => tv += 1,
                    }
                }
                b'b' | b'd' | b'h' | b'v' => n3 += 1,
                b'n' | b'x' => n4 += 1,
                _ => {}
            }
        }
        for pair in record.seq.windows(2) {
            if pair[0].eq_ignore_ascii_case(&b'C') && pair[1].eq_ignore_ascii_case(&b'G') {
                cpg_bases += 2;
                if matches!(pair[0].to_ascii_lowercase(), b'y') || matches!(pair[1].to_ascii_lowercase(), b'r') {
                    cpg_ts += 1;
                }
            }
        }
        let _ = writeln!(
            out,
            "{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",
            record.name,
            record.seq.len(),
            a,
            c,
            g,
            t,
            n2,
            n3,
            n4,
            cpg_bases,
            tv,
            ts,
            cpg_ts
        );
    }
    0
}

#[derive(Default)]
struct SeqOptions {
    to_fasta: bool,
    strip_comment: bool,
    revcomp: bool,
    dup_revcomp: bool,
    uppercase: bool,
    only_clean: bool,
    odd_only: bool,
    even_only: bool,
    line_len: usize,
    qual_thresh: Option<i32>,
    qual_shift: i32,
    lowqual_mask: Option<u8>,
    fill_qual: Option<u8>,
    min_len: usize,
    mask_file: Option<String>,
}

fn cmd_seq(args: &[String]) -> i32 {
    let mut opts = SeqOptions {
        line_len: 0,
        qual_shift: 33,
        ..SeqOptions::default()
    };
    let mut input: Option<String> = None;
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if input.is_none() && arg.starts_with('-') && arg != "-" {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut pos = 0usize;
            while pos < chars.len() {
                match chars[pos] {
                    'a' | 'A' => opts.to_fasta = true,
                    'C' => opts.strip_comment = true,
                    'r' => opts.revcomp = true,
                    'R' => opts.dup_revcomp = true,
                    'U' => opts.uppercase = true,
                    'N' => opts.only_clean = true,
                    '1' => opts.odd_only = true,
                    '2' => opts.even_only = true,
                    'c' | 'x' | 'S' | 'V' => {}
                    'l' => {
                        let value = take_short_value("seq", 'l', &chars, &mut pos, args, &mut i);
                        let Some(value) = value else {
                            return 0;
                        };
                        opts.line_len = parse_usize(&value, 0);
                        break;
                    }
                    'q' => {
                        let value = take_short_value("seq", 'q', &chars, &mut pos, args, &mut i);
                        let Some(value) = value else {
                            return 0;
                        };
                        opts.qual_thresh = Some(parse_i32(&value, 0));
                        break;
                    }
                    'Q' => {
                        let value = take_short_value("seq", 'Q', &chars, &mut pos, args, &mut i);
                        let Some(value) = value else {
                            return 0;
                        };
                        opts.qual_shift = parse_i32(&value, 33);
                        break;
                    }
                    'n' => {
                        let value = take_short_value("seq", 'n', &chars, &mut pos, args, &mut i);
                        let Some(value) = value else {
                            return 0;
                        };
                        opts.lowqual_mask = value.as_bytes().first().copied();
                        break;
                    }
                    'F' => {
                        let value = take_short_value("seq", 'F', &chars, &mut pos, args, &mut i);
                        let Some(value) = value else {
                            return 0;
                        };
                        opts.fill_qual = value.as_bytes().first().copied();
                        break;
                    }
                    'L' => {
                        let value = take_short_value("seq", 'L', &chars, &mut pos, args, &mut i);
                        let Some(value) = value else {
                            return 0;
                        };
                        opts.min_len = parse_usize(&value, 0);
                        break;
                    }
                    'M' => {
                        let value = take_short_value("seq", 'M', &chars, &mut pos, args, &mut i);
                        let Some(value) = value else {
                            return 0;
                        };
                        opts.mask_file = Some(value);
                        break;
                    }
                    'f' | 's' | 'X' => {
                        let _ = take_short_value("seq", chars[pos], &chars, &mut pos, args, &mut i);
                        break;
                    }
                    other => {
                        eprintln!("seq: invalid option -- '{other}'");
                        return 0;
                    }
                }
                pos += 1;
            }
        } else {
            input = Some(arg.clone());
        }
        i += 1;
    }

    let masks = match opts.mask_file.as_deref() {
        Some(path) => match read_bed_mask(path) {
            Ok(v) => v,
            Err(_) => {
                eprintln!("[E::stk_seq] failed to open the input file/stream.");
                return 1;
            }
        },
        None => HashMap::new(),
    };

    let (records, format) = match read_fastx(input.as_deref()) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_seq] failed to open the input file/stream.");
            return 1;
        }
    };
    let output_format = if opts.to_fasta {
        Format::Fasta
    } else {
        format.unwrap_or(Format::Fasta)
    };

    let mut out = BufWriter::new(io::stdout().lock());
    for (idx, mut record) in records.into_iter().enumerate() {
        let nth = idx + 1;
        if opts.odd_only && nth % 2 == 0 {
            continue;
        }
        if opts.even_only && nth % 2 == 1 {
            continue;
        }
        if opts.uppercase {
            upper_seq(&mut record.seq);
        }
        if let Some(fill) = opts.fill_qual {
            if let Some(qual) = record.qual.as_mut() {
                for q in qual {
                    *q = fill;
                }
            }
        }
        if let Some(thresh) = opts.qual_thresh {
            if let Some(qual) = record.qual.as_deref() {
                for (base, &q) in record.seq.iter_mut().zip(qual.iter()) {
                    let score = q as i32 - opts.qual_shift;
                    if score < thresh {
                        *base = opts.lowqual_mask.unwrap_or_else(|| base.to_ascii_lowercase());
                    }
                }
            }
        }
        if let Some(intervals) = masks.get(&record.name) {
            apply_mask(&mut record.seq, intervals);
        }
        if opts.only_clean
            && record
                .seq
                .iter()
                .any(|&b| !matches!(b.to_ascii_lowercase(), b'a' | b'c' | b'g' | b't' | b'u'))
        {
            continue;
        }
        if record.seq.len() < opts.min_len {
            continue;
        }
        if opts.strip_comment {
            record.comment = None;
        }
        if opts.dup_revcomp {
            let mut plus = record.clone();
            plus.name.push('+');
            let mut minus = record;
            minus.name.push('-');
            minus.seq = reverse_complement(&minus.seq);
            if let Some(qual) = minus.qual.as_mut() {
                qual.reverse();
            }
            let _ = write_record(&mut out, &plus, output_format, opts.line_len, None);
            let _ = write_record(&mut out, &minus, output_format, opts.line_len, None);
            continue;
        }
        if opts.revcomp {
            record.seq = reverse_complement(&record.seq);
            if let Some(qual) = record.qual.as_mut() {
                qual.reverse();
            }
        }
        let _ = write_record(&mut out, &record, output_format, opts.line_len, None);
    }
    0
}

fn cmd_sample(args: &[String]) -> i32 {
    let mut two_pass = false;
    let mut seed: u64 = 11;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            if arg == "-2" {
                two_pass = true;
            } else if let Some(rest) = arg.strip_prefix("-s") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{SAMPLE_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                seed = value.parse::<u64>().unwrap_or(11);
            } else {
                print!("{SAMPLE_USAGE}");
                return 1;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    if positional.len() < 2 {
        print!("{SAMPLE_USAGE}");
        return 1;
    }
    let input = &positional[0];
    let sample_arg = &positional[1];
    let (records, format) = match read_fastx(Some(input)) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_sample] failed to open the input file/stream.");
            return 1;
        }
    };
    let out_format = format.unwrap_or(Format::Fasta);
    let mut out = BufWriter::new(io::stdout().lock());
    if let Ok(n) = sample_arg.parse::<usize>() {
        let mut rng = SeqRng::new(seed);
        let mut reservoir: Vec<(usize, Record)> = Vec::new();
        for (idx, record) in records.into_iter().enumerate() {
            if idx < n {
                reservoir.push((idx, record));
            } else if n > 0 {
                let j = (rng.next_f64() * (idx as f64 + 1.0)).floor() as usize;
                if j < n {
                    reservoir[j] = (idx, record);
                }
            }
        }
        if two_pass {
            reservoir.sort_by_key(|(idx, _)| *idx);
        }
        for (_, record) in reservoir {
            let _ = write_record(&mut out, &record, out_format, 0, None);
        }
    } else {
        let frac = sample_arg.parse::<f64>().unwrap_or(0.0);
        if two_pass {
            eprintln!("[W::stk_sample] when sampling a fraction, option -2 is ignored.");
        }
        let mut rng = SeqRng::new(seed);
        for record in records {
            if rng.next_f64() < frac {
                let _ = write_record(&mut out, &record, out_format, 0, None);
            }
        }
    }
    0
}

#[derive(Clone, Debug)]
struct Region {
    start: usize,
    end: usize,
    strand: Option<char>,
}

enum Selector {
    Names(HashSet<String>),
    Regions(HashMap<String, Vec<Region>>),
}

fn cmd_subseq(args: &[String]) -> i32 {
    let mut tab = false;
    let mut strand = false;
    let mut line_len = 0usize;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut pos = 0usize;
            while pos < chars.len() {
                match chars[pos] {
                    't' => tab = true,
                    's' => strand = true,
                    'l' => {
                        let value =
                            take_short_value("subseq", 'l', &chars, &mut pos, args, &mut i);
                        let Some(value) = value else {
                            print!("{SUBSEQ_USAGE}");
                            return 1;
                        };
                        line_len = parse_usize(&value, 0);
                        break;
                    }
                    other => {
                        eprintln!("subseq: invalid option -- '{other}'");
                        print!("{SUBSEQ_USAGE}");
                        return 1;
                    }
                }
                pos += 1;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    if positional.len() < 2 {
        print!("{SUBSEQ_USAGE}");
        return 1;
    }
    let input = &positional[0];
    let spec = match read_selector(&positional[1]) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_subseq] failed to open the input file/stream.");
            return 1;
        }
    };
    let (records, format) = match read_fastx(Some(input)) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_subseq] failed to open the input file/stream.");
            return 1;
        }
    };
    let mut out = BufWriter::new(io::stdout().lock());
    match spec {
        Selector::Names(names) => {
            for record in records {
                if names.contains(&record.name) {
                    let _ = write_record(&mut out, &record, record_format(&record), 0, None);
                }
            }
        }
        Selector::Regions(regions) => {
            for record in records {
                let Some(regs) = regions.get(&record.name) else {
                    continue;
                };
                for reg in regs {
                    let start = min(reg.start, record.seq.len());
                    let end = min(max(reg.end, start), record.seq.len());
                    let mut seq = record.seq[start..end].to_vec();
                    let mut qual = record.qual.as_ref().map(|q| q[start..end].to_vec());
                    if strand && matches!(reg.strand, Some('-')) {
                        seq = reverse_complement(&seq);
                        if let Some(q) = qual.as_mut() {
                            q.reverse();
                        }
                    }
                    let header = format!("{}:{}-{}", record.name, start + 1, end);
                    if tab {
                        if strand {
                            let _ = writeln!(out, "{}\t{}\t", record.name, start + 1);
                            let _ = writeln!(out, "{}", String::from_utf8_lossy(&seq));
                        } else {
                            let _ = writeln!(
                                out,
                                "{}\t{}\t{}",
                                record.name,
                                start + 1,
                                String::from_utf8_lossy(&seq)
                            );
                        }
                    } else if strand && format == Some(Format::Fastq) {
                        let _ = write_record_with_header(
                            &mut out,
                            '@',
                            &header,
                            record.comment.as_deref(),
                            &seq,
                            None,
                            line_len,
                        );
                    } else {
                        let qual_ref = if strand { qual.as_deref() } else { qual.as_deref() };
                        let _ = write_record_with_header(
                            &mut out,
                            if format == Some(Format::Fastq) { '@' } else { '>' },
                            &header,
                            record.comment.as_deref(),
                            &seq,
                            if format == Some(Format::Fastq) && !strand {
                                qual_ref
                            } else {
                                None
                            },
                            line_len,
                        );
                    }
                }
            }
        }
    }
    0
}

fn cmd_fqchk(args: &[String]) -> i32 {
    let mut qcut = 20i32;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            if let Some(rest) = arg.strip_prefix("-q") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{FQCHK_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                qcut = parse_i32(&value, 20);
            } else {
                print!("{FQCHK_USAGE}");
                return 1;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    if positional.is_empty() {
        print!("{FQCHK_USAGE}");
        return 1;
    }
    let (records, _) = match read_fastx(Some(&positional[0])) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_fqchk] failed to open the input file/stream.");
            return 1;
        }
    };
    let mut min_len = usize::MAX;
    let mut max_len = 0usize;
    let mut total_len = 0usize;
    let mut distinct = BTreeSet::new();
    let mut rows: Vec<PosStats> = Vec::new();
    let mut all = PosStats::default();
    for record in &records {
        min_len = min(min_len, record.seq.len());
        max_len = max(max_len, record.seq.len());
        total_len += record.seq.len();
        let Some(qual) = record.qual.as_deref() else {
            continue;
        };
        if rows.len() < record.seq.len() {
            rows.resize_with(record.seq.len(), PosStats::default);
        }
        for (idx, (&base, &q)) in record.seq.iter().zip(qual.iter()).enumerate() {
            let score = q.saturating_sub(33) as i32;
            distinct.insert(score);
            rows[idx].add(base, score, qcut);
            all.add(base, score, qcut);
        }
    }
    if min_len == usize::MAX {
        min_len = 0;
    }
    println!(
        "min_len: {}; max_len: {}; avg_len: {:.2}; {} distinct quality values",
        min_len,
        max_len,
        if records.is_empty() {
            0.0
        } else {
            total_len as f64 / records.len() as f64
        },
        distinct.len()
    );
    println!("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high");
    print_pos_stats("ALL", &all);
    for (idx, stats) in rows.iter().enumerate() {
        print_pos_stats(&(idx + 1).to_string(), stats);
    }
    0
}

