fn cmd_split(args: &[String]) -> i32 {
    let mut n = 10usize;
    let mut line_len = 0usize;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            if let Some(rest) = arg.strip_prefix("-n") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{SPLIT_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                n = parse_usize(&value, 10);
            } else if let Some(rest) = arg.strip_prefix("-l") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{SPLIT_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                line_len = parse_usize(&value, 0);
            } else {
                print!("{SPLIT_USAGE}");
                return 1;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    if positional.len() < 2 {
        print!("{SPLIT_USAGE}");
        return 1;
    }
    let prefix = &positional[0];
    let (records, format) = match read_fastx(Some(&positional[1])) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_split] failed to open the input file/stream.");
            return 1;
        }
    };
    let ext = if format == Some(Format::Fastq) { "fq" } else { "fa" };
    let mut writers = Vec::new();
    for idx in 1..=n {
        let path = format!("{prefix}.{idx:05}.{ext}");
        let file = match File::create(&path) {
            Ok(f) => f,
            Err(_) => return 1,
        };
        writers.push(BufWriter::new(file));
