    for (idx, record) in records.iter().enumerate() {
        let bucket = idx % n;
        let _ = write_record(&mut writers[bucket], record, record_format(record), line_len, None);
    }
    0
}

fn cmd_trimfq(args: &[String]) -> i32 {
    let mut err_rate = 0.05f64;
    let mut min_len = 30usize;
    let mut trim_left = 0usize;
    let mut trim_right = 0usize;
    let mut keep_left = 0usize;
    let mut force_fastq = false;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            if let Some(rest) = arg.strip_prefix("-q") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{TRIMFQ_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                err_rate = value.parse::<f64>().unwrap_or(0.05);
            } else if let Some(rest) = arg.strip_prefix("-l") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{TRIMFQ_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                min_len = parse_usize(&value, 30);
            } else if let Some(rest) = arg.strip_prefix("-b") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{TRIMFQ_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                trim_left = parse_usize(&value, 0);
            } else if let Some(rest) = arg.strip_prefix("-e") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{TRIMFQ_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                trim_right = parse_usize(&value, 0);
            } else if let Some(rest) = arg.strip_prefix("-L") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{TRIMFQ_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                keep_left = parse_usize(&value, 0);
            } else if arg == "-Q" {
                force_fastq = true;
            } else {
                eprintln!("trimfq: invalid option -- '{}'", arg.trim_start_matches('-'));
                print!("{TRIMFQ_USAGE}");
                return 1;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    if positional.is_empty() {
        print!("{TRIMFQ_USAGE}");
        return 1;
    }
    let (records, format) = match read_fastx(Some(&positional[0])) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_trimfq] failed to open the input file/stream.");
            return 1;
        }
    };
    let default_fastq = format == Some(Format::Fastq) || force_fastq;
    let qcut = (-10.0 * err_rate.log10()).floor() as i32;
    let mut out = BufWriter::new(io::stdout().lock());
    for mut record in records {
        if keep_left > 0 {
            truncate_record(&mut record, 0, min(record.seq.len(), keep_left));
        } else if trim_left > 0 || trim_right > 0 {
            let start = min(trim_left, record.seq.len());
            let end = record.seq.len().saturating_sub(trim_right);
            truncate_record(&mut record, start, max(start, end));
        } else if let Some(qual) = record.qual.as_deref() {
            if record.seq.len() > min_len {
                let mut start = 0usize;
                let mut end = record.seq.len();
                while end.saturating_sub(start) > min_len
                    && qual.get(start).map(|q| (*q as i32 - 33) < qcut).unwrap_or(false)
                {
                    start += 1;
                }
                while end.saturating_sub(start) > min_len
                    && qual
                        .get(end.saturating_sub(1))
                        .map(|q| (*q as i32 - 33) < qcut)
                        .unwrap_or(false)
                {
                    end = end.saturating_sub(1);
                }
                truncate_record(&mut record, start, end);
            }
        }
        let format = if default_fastq { Format::Fastq } else { Format::Fasta };
        if format == Format::Fastq && record.qual.is_none() {
            record.qual = Some(vec![b'I'; record.seq.len()]);
        }
        let _ = write_record(&mut out, &record, format, 0, None);
    }
    0
}

fn cmd_hety(args: &[String]) -> i32 {
    let mut window = 50_000usize;
    let mut _threshold = 5usize;
    let mut mask_lower = false;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            if let Some(rest) = arg.strip_prefix("-w") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{HETY_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                window = parse_usize(&value, 50_000);
            } else if let Some(rest) = arg.strip_prefix("-t") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{HETY_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                _threshold = parse_usize(&value, 5);
            } else if arg == "-m" {
                mask_lower = true;
            } else {
                print!("{HETY_USAGE}");
                return 1;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    if positional.is_empty() {
        print!("{HETY_USAGE}");
        return 1;
    }
    let (records, _) = match read_fastx(Some(&positional[0])) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_hety] failed to open the input file/stream.");
            return 1;
        }
    };
    for record in records {
        let mut start = 0usize;
        while start < record.seq.len() || (start == 0 && record.seq.is_empty()) {
            let end = min(record.seq.len(), start + window);
            let slice = &record.seq[start..end];
            let mut hom = 0usize;
            let mut het = 0usize;
            for &base in slice {
                if mask_lower && base.is_ascii_lowercase() {
                    continue;
                }
                if is_het2(base) {
                    het += 1;
                } else {
                    hom += 1;
                }
            }
            let rate = if hom == 0 {
                0.0
            } else {
                100000.0 * het as f64 / (2.0 * hom as f64)
            };
            println!(
                "{}\t{}\t{}\t{:.2}\t{}\t{}",
                record.name,
                start,
                end.saturating_sub(start),
                rate,
                hom,
                het
            );
            if end >= record.seq.len() {
                break;
            }
            start += window;
        }
    }
    0
}

fn cmd_gc(args: &[String]) -> i32 {
    let mut at_mode = false;
    let mut frac = 0.60f64;
    let mut min_len = 20usize;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            if arg == "-w" {
                at_mode = true;
            } else if let Some(rest) = arg.strip_prefix("-f") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{GC_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                frac = value.parse::<f64>().unwrap_or(0.60);
            } else if let Some(rest) = arg.strip_prefix("-l") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{GC_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                min_len = parse_usize(&value, 20);
            } else if arg.starts_with("-x") {
                if arg == "-x" {
                    i += 1;
                }
            } else {
                print!("{GC_USAGE}");
                return 1;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    if positional.is_empty() {
        print!("{GC_USAGE}");
        return 1;
    }
    let (records, _) = match read_fastx(Some(&positional[0])) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_gc] failed to open the input file/stream.");
            return 1;
        }
    };
    for record in records {
        let mut run_start: Option<usize> = None;
        for (idx, &base) in record.seq.iter().enumerate() {
            let hit = if at_mode {
                matches!(base.to_ascii_lowercase(), b'a' | b't')
            } else {
                matches!(base.to_ascii_lowercase(), b'g' | b'c')
            };
            if hit {
                run_start.get_or_insert(idx);
            } else if let Some(start) = run_start.take() {
                let end = idx;
                let len = end - start;
                if len >= min_len {
                    let ratio = 1.0f64;
                    if ratio >= frac {
                        println!("{}\t{}\t{}", record.name, start, end);
                    }
                }
            }
        }
        if let Some(start) = run_start.take() {
            let end = record.seq.len();
            let len = end - start;
            if len >= min_len && 1.0 >= frac {
                println!("{}\t{}\t{}", record.name, start, end);
            }
        }
    }
    0
}

fn cmd_mutfa(args: &[String]) -> i32 {
    if args.len() < 2 {
        print!("{MUTFA_USAGE}");
        return 1;
    }
    let mut snps = HashMap::<String, Vec<(usize, u8)>>::new();
    if let Ok(file) = File::open(&args[1]) {
        for line in BufReader::new(file).lines().map_while(Result::ok) {
            let fields: Vec<&str> = line.split_whitespace().collect();
            if fields.len() >= 4 {
                let pos = fields[1].parse::<usize>().unwrap_or(1).saturating_sub(1);
                if let Some(&base) = fields[3].as_bytes().first() {
                    snps.entry(fields[0].to_string()).or_default().push((pos, base));
                }
            }
        }
    } else {
        eprintln!("[E::stk_mutfa] failed to open the input file/stream.");
        return 1;
    }
    let (mut records, _) = match read_fastx(Some(&args[0])) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_mutfa] failed to open the input file/stream.");
            return 1;
        }
    };
    let mut out = BufWriter::new(io::stdout().lock());
    for record in records.iter_mut() {
        if let Some(changes) = snps.get(&record.name) {
            for &(pos, base) in changes {
                if pos < record.seq.len() {
                    record.seq[pos] = base;
                }
            }
        }
        record.comment = None;
        let _ = write_record(&mut out, record, Format::Fasta, 0, None);
    }
    0
}

fn cmd_mergefa(args: &[String]) -> i32 {
    let mut qcut = 0i32;
    let mut intersect = false;
    let mut lower_n = false;
    let mut random_het = false;
    let mut suppress_het = false;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            if let Some(rest) = arg.strip_prefix("-q") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{MERGEFA_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                qcut = parse_i32(&value, 0);
            } else if arg == "-i" {
                intersect = true;
            } else if arg == "-m" {
                lower_n = true;
            } else if arg == "-r" {
                random_het = true;
            } else if arg == "-h" {
                suppress_het = true;
            } else {
                print!("{MERGEFA_USAGE}");
                return 1;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    if positional.len() < 2 {
        print!("{MERGEFA_USAGE}");
        return 1;
    }
    let (left, _) = match read_fastx(Some(&positional[0])) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_mergefa] failed to open the input file/stream.");
            return 1;
        }
    };
    let (right, _) = match read_fastx(Some(&positional[1])) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_mergefa] failed to open the input file/stream.");
            return 1;
        }
    };
    let mut stats = [0usize; 5];
    let mut rng = SeqRng::new(11);
    let mut out = BufWriter::new(io::stdout().lock());
    let count = max(left.len(), right.len());
    for idx in 0..count {
        let a = left.get(idx);
        let b = right.get(idx);
        let Some(name) = a.map(|r| r.name.clone()).or_else(|| b.map(|r| r.name.clone())) else {
            continue;
        };
        if let (Some(ar), Some(br)) = (a, b) {
            if ar.name != br.name {
                eprintln!("[stk_mergefa] Different sequence names: {} != {}", ar.name, br.name);
            }
            if ar.seq.len() != br.seq.len() {
                eprintln!(
                    "[stk_mergefa] Unequal sequence length: {} != {}",
                    ar.seq.len(),
                    br.seq.len()
                );
            }
        }
        let len = max(a.map_or(0, Record::len), b.map_or(0, Record::len));
        let mut merged = Vec::with_capacity(len);
        for pos in 0..len {
            let ba = a.and_then(|r| r.seq.get(pos).copied()).unwrap_or(b'N');
            let bb = b.and_then(|r| r.seq.get(pos).copied()).unwrap_or(b'N');
            let qa = a.and_then(|r| r.qual.as_ref()).and_then(|q| q.get(pos).copied());
            let qb = b.and_then(|r| r.qual.as_ref()).and_then(|q| q.get(pos).copied());
            let mut left_base = ba;
            let mut right_base = bb;
            if suppress_het {
                if is_het2(left_base) {
                    left_base = if left_base.is_ascii_lowercase() { b'n' } else { b'N' };
                }
                if is_het2(right_base) {
                    right_base = if right_base.is_ascii_lowercase() { b'n' } else { b'N' };
                }
            }
            let left_bits = allele_bits(left_base);
            let right_bits = allele_bits(right_base);
            if left_bits == right_bits && left_bits.count_ones() == 1 {
                stats[0] += 1;
            } else if left_bits.count_ones() == 1 && right_bits.count_ones() == 1 {
                stats[1] += 1;
            } else if left_bits.count_ones() == 1 && right_bits.count_ones() == 2 {
                stats[2] += 1;
            } else if left_bits.count_ones() == 2 && right_bits.count_ones() == 1 {
                stats[3] += 1;
            } else if left_bits.count_ones() == 2 && right_bits.count_ones() == 2 {
                stats[4] += 1;
            }
            let lower = left_base.is_ascii_lowercase() || right_base.is_ascii_lowercase();
            let mut out_base = if lower_n && (is_n(left_base) || is_n(right_base)) {
                let other = if is_n(left_base) { right_base } else { left_base };
                if is_n(other) {
                    b'n'
                } else {
                    other.to_ascii_lowercase()
                }
            } else if random_het && (is_n(left_base) || is_n(right_base)) {
                if is_n(left_base) && !is_n(right_base) {
                    right_base.to_ascii_lowercase()
                } else if is_n(right_base) && !is_n(left_base) {
                    left_base.to_ascii_lowercase()
                } else {
                    b'n'
                }
            } else {
                let bits = if intersect {
                    left_bits & right_bits
                } else {
                    left_bits | right_bits
                };
                let empty = if lower { b'x' } else { b'X' };
                encode_alleles(bits, lower, empty)
            };
            if qcut > 0 {
                let low = qa.map(|q| (q as i32 - 33) < qcut).unwrap_or(false)
                    || qb.map(|q| (q as i32 - 33) < qcut).unwrap_or(false);
                if low {
                    out_base = out_base.to_ascii_lowercase();
                }
            }
            if random_het && is_het2(out_base) {
                let alleles = decode_het2(out_base);
                out_base = alleles[(rng.next_u64() & 1) as usize];
                if lower {
                    out_base = out_base.to_ascii_lowercase();
                }
            }
            merged.push(out_base);
        }
        let _ = writeln!(
            io::stderr(),
            "[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=({},{},{},{},{})",
            stats[0], stats[1], stats[2], stats[3], stats[4]
        );
        stats = [0; 5];
        let record = Record {
            name,
            comment: None,
            seq: merged,
            qual: None,
        };
        let _ = write_record(&mut out, &record, Format::Fasta, 0, None);
    }
    0
}

