fn cmd_cutn(args: &[String]) -> i32 {
    let mut min_n = 1000usize;
    let mut _penalty = 10usize;
    let mut gaps_only = false;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            if let Some(rest) = arg.strip_prefix("-n") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{CUTN_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                min_n = parse_usize(&value, 1000);
            } else if let Some(rest) = arg.strip_prefix("-p") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{CUTN_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                _penalty = parse_usize(&value, 10);
            } else if arg == "-g" {
                gaps_only = true;
            } else {
                print!("{CUTN_USAGE}");
                return 1;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    if positional.is_empty() {
        print!("{CUTN_USAGE}");
        return 1;
    }
    let (records, _) = match read_fastx(Some(&positional[0])) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_cutN] failed to open the input file/stream.");
            return 1;
        }
    };
    let mut out = BufWriter::new(io::stdout().lock());
    for record in records {
        let gaps = n_tracts(&record.seq, min_n);
        if gaps_only {
            for (s, e) in gaps.iter().copied() {
                if s > 0 && e < record.seq.len() {
                    let _ = writeln!(out, "{}\t{}\t{}", record.name, s, e);
                }
            }
            continue;
        }
        let mut start = 0usize;
        for (s, e) in gaps {
            if start < s {
                let frag = Record {
                    name: format!("{}:{}-{}", record.name, start + 1, s),
                    comment: None,
                    seq: record.seq[start..s].to_vec(),
                    qual: None,
                };
                let _ = write_record(&mut out, &frag, Format::Fasta, 0, None);
            }
            start = e;
        }
        if start < record.seq.len() {
            let frag = Record {
                name: format!("{}:{}-{}", record.name, start + 1, record.seq.len()),
                comment: None,
                seq: record.seq[start..].to_vec(),
                qual: None,
            };
            let _ = write_record(&mut out, &frag, Format::Fasta, 0, None);
        }
    }
    0
}

