#[derive(Default, Clone)]
struct PosStats {
    bases: usize,
    a: usize,
    c: usize,
    g: usize,
    t: usize,
    n: usize,
    q_sum: i64,
    err_sum: f64,
    low: usize,
    high: usize,
}

impl PosStats {
    fn add(&mut self, base: u8, q: i32, qcut: i32) {
        self.bases += 1;
        match base.to_ascii_lowercase() {
            b'a' => self.a += 1,
            b'c' => self.c += 1,
            b'g' => self.g += 1,
            b't' | b'u' => self.t += 1,
            _ => self.n += 1,
        }
        self.q_sum += q as i64;
        self.err_sum += 10f64.powf(-(q as f64) / 10.0);
        if q < qcut {
            self.low += 1;
        } else {
            self.high += 1;
        }
    }
}

fn print_pos_stats(label: &str, stats: &PosStats) {
    if stats.bases == 0 {
        println!("{label}\t0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0");
        return;
    }
    let denom = stats.bases as f64;
    let avg_q = stats.q_sum as f64 / denom;
    let err_q = -10.0 * (stats.err_sum / denom).log10();
    println!(
        "{label}\t{}\t{:.1}\t{:.1}\t{:.1}\t{:.1}\t{:.1}\t{:.1}\t{:.1}\t{:.1}\t{:.1}",
        stats.bases,
        100.0 * stats.a as f64 / denom,
        100.0 * stats.c as f64 / denom,
        100.0 * stats.g as f64 / denom,
        100.0 * stats.t as f64 / denom,
        100.0 * stats.n as f64 / denom,
        avg_q,
        err_q,
        100.0 * stats.low as f64 / denom,
        100.0 * stats.high as f64 / denom
    );
}

fn read_bed_mask(path: &str) -> io::Result<HashMap<String, Vec<(usize, usize)>>> {
    let file = File::open(path)?;
    let mut map = HashMap::new();
    for line in BufReader::new(file).lines().map_while(Result::ok) {
        let fields: Vec<&str> = line.split_whitespace().collect();
        if fields.len() >= 3 {
            let start = fields[1].parse::<usize>().unwrap_or(0);
            let end = fields[2].parse::<usize>().unwrap_or(start);
            map.entry(fields[0].to_string()).or_insert_with(Vec::new).push((start, end));
        }
    }
    Ok(map)
}

fn apply_mask(seq: &mut [u8], intervals: &[(usize, usize)]) {
    for &(start, end) in intervals {
        let start = min(start, seq.len());
        let end = min(max(end, start), seq.len());
        for base in &mut seq[start..end] {
            *base = lower_base(*base);
        }
    }
}

fn read_selector(path: &str) -> io::Result<Selector> {
    let file = File::open(path)?;
    let lines: Vec<String> = BufReader::new(file).lines().map_while(Result::ok).collect();
    let mut nonempty = lines.iter().find(|l| !l.trim().is_empty()).cloned().unwrap_or_default();
    if nonempty.is_empty() {
        return Ok(Selector::Names(HashSet::new()));
    }
    let fields: Vec<&str> = nonempty.split_whitespace().collect();
    if fields.len() >= 3
        && fields[1].parse::<usize>().is_ok()
        && fields[2].parse::<usize>().is_ok()
    {
        let mut map: HashMap<String, Vec<Region>> = HashMap::new();
        for line in lines {
            let cols: Vec<&str> = line.split_whitespace().collect();
            if cols.len() >= 3 {
                let start = cols[1].parse::<usize>().unwrap_or(0);
                let end = cols[2].parse::<usize>().unwrap_or(start);
                let strand = cols.get(5).and_then(|s| s.chars().next());
                map.entry(cols[0].to_string())
                    .or_default()
                    .push(Region { start, end, strand });
            }
        }
        Ok(Selector::Regions(map))
    } else {
        let names = lines
            .into_iter()
            .filter_map(|line| line.split_whitespace().next().map(ToString::to_string))
            .collect();
        Ok(Selector::Names(names))
    }
}

fn take_short_value(
    cmd: &str,
    opt: char,
    chars: &[char],
    pos: &mut usize,
    args: &[String],
    idx: &mut usize,
) -> Option<String> {
    if *pos + 1 < chars.len() {
        let value: String = chars[*pos + 1..].iter().collect();
        *pos = chars.len();
        Some(value)
    } else {
        *idx += 1;
        if *idx >= args.len() {
            eprintln!("{cmd}: option requires an argument -- '{opt}'");
            None
        } else {
            Some(args[*idx].clone())
        }
    }
}

fn parse_usize(value: &str, default: usize) -> usize {
    value.parse::<usize>().unwrap_or(default)
}

fn parse_i32(value: &str, default: i32) -> i32 {
    value.parse::<i32>().unwrap_or(default)
}

fn truncate_record(record: &mut Record, start: usize, end: usize) {
    let start = min(start, record.seq.len());
    let end = min(max(end, start), record.seq.len());
    record.seq = record.seq[start..end].to_vec();
    if let Some(qual) = record.qual.as_mut() {
        *qual = qual[start..end].to_vec();
    }
}

fn pair_key(name: &str) -> &str {
    if let Some(prefix) = name.strip_suffix("/1") {
        prefix
    } else if let Some(prefix) = name.strip_suffix("/2") {
        prefix
    } else {
        name
    }
}

fn n_tracts(seq: &[u8], min_len: usize) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut i = 0usize;
    while i < seq.len() {
        if is_n(seq[i]) {
            let start = i;
            while i < seq.len() && is_n(seq[i]) {
                i += 1;
            }
            if i - start >= min_len {
                out.push((start, i));
            }
        } else {
            i += 1;
        }
    }
    out
}

fn decode_het2(base: u8) -> [u8; 2] {
    let lower = base.is_ascii_lowercase();
    let pair = match base.to_ascii_lowercase() {
        b'r' => [b'A', b'G'],
        b'y' => [b'C', b'T'],
        b'k' => [b'G', b'T'],
        b'm' => [b'A', b'C'],
        b's' => [b'C', b'G'],
        b'w' => [b'A', b'T'],
        _ => [base.to_ascii_uppercase(), base.to_ascii_uppercase()],
    };
    if lower {
        [pair[0].to_ascii_lowercase(), pair[1].to_ascii_lowercase()]
    } else {
        pair
    }
}

fn telo_hits(seq: &[u8]) -> Vec<(usize, usize)> {
    let motifs = [b"TTAGGG".as_slice(), b"CCCTAA".as_slice()];
    let mut hits = Vec::new();
    for motif in motifs {
        let mut i = 0usize;
        while i + motif.len() <= seq.len() {
            if seq[i..].starts_with(motif) {
                let start = i;
                while i + motif.len() <= seq.len() && seq[i..].starts_with(motif) {
                    i += motif.len();
                }
                if i - start >= motif.len() * 4 {
                    hits.push((start, i));
                }
            } else {
                i += 1;
            }
        }
    }
    hits.sort_unstable();
    hits
}

struct SeqRng {
    state: u64,
}

impl SeqRng {
    fn new(seed: u64) -> Self {
        Self {
            state: seed ^ 0x9e3779b97f4a7c15,
        }
    }

    fn next_u64(&mut self) -> u64 {
        self.state ^= self.state >> 12;
        self.state ^= self.state << 25;
        self.state ^= self.state >> 27;
        self.state = self.state.wrapping_mul(0x2545F4914F6CDD1D);
        self.state
    }

    fn next_f64(&mut self) -> f64 {
        ((self.next_u64() >> 11) as f64) / ((1u64 << 53) as f64)
    }
}

