#include <bits/stdc++.h>
using namespace std; using U=uint64_t; using V=vector<int>;
map<int,V> want={{1,{8,5,3}},{11,{5,6,4}},{100,{2,4,6}}};

struct mt64u { mt19937_64 g; mt64u(U s):g(s){} U raw(){return g();} int ui(int n){uniform_int_distribution<int>d(0,n-1); return d(g);} double uf(){uniform_real_distribution<double>d(0,1); return d(g);} };
struct mt32u { mt19937 g; mt32u(U s):g(s){} U raw(){return g();} int ui(int n){uniform_int_distribution<int>d(0,n-1); return d(g);} double uf(){uniform_real_distribution<double>d(0,1); return d(g);} };

// draw methods
#define METHOD(name, body) template<class R> V name(int N,int K,U seed){ R r(seed); body }
METHOD(draw_remove_ui, {V v(N); iota(v.begin(),v.end(),1); V o; for(int i=0;i<K;i++){int j=r.ui(v.size()); o.push_back(v[j]); v.erase(v.begin()+j);} return o;})
METHOD(draw_remove_mod, {V v(N); iota(v.begin(),v.end(),1); V o; for(int i=0;i<K;i++){int j=r.raw()%v.size(); o.push_back(v[j]); v.erase(v.begin()+j);} return o;})
METHOD(draw_remove_real, {V v(N); iota(v.begin(),v.end(),1); V o; for(int i=0;i<K;i++){int j=(int)(r.uf()*v.size()); if(j==(int)v.size()) j=v.size()-1; o.push_back(v[j]); v.erase(v.begin()+j);} return o;})
METHOD(draw_swap_ui, {V v(N); iota(v.begin(),v.end(),1); V o; for(int i=0;i<K;i++){int j=i+r.ui(N-i); swap(v[i],v[j]); o.push_back(v[i]);} return o;})
METHOD(draw_swap_mod, {V v(N); iota(v.begin(),v.end(),1); V o; for(int i=0;i<K;i++){int j=i+(r.raw()%(N-i)); swap(v[i],v[j]); o.push_back(v[i]);} return o;})
METHOD(draw_swap_real, {V v(N); iota(v.begin(),v.end(),1); V o; for(int i=0;i<K;i++){int j=i+(int)(r.uf()*(N-i)); if(j>=N) j=N-1; swap(v[i],v[j]); o.push_back(v[i]);} return o;})
METHOD(draw_tail_ui, {V v(N); iota(v.begin(),v.end(),1); for(int i=0;i<K;i++){int j=r.ui(N-i); swap(v[N-1-i],v[j]);} reverse(v.end()-K,v.end()); return V(v.end()-K,v.end());})
METHOD(draw_tail_mod, {V v(N); iota(v.begin(),v.end(),1); for(int i=0;i<K;i++){int j=r.raw()%(N-i); swap(v[N-1-i],v[j]);} reverse(v.end()-K,v.end()); return V(v.end()-K,v.end());})
METHOD(draw_tail_real, {V v(N); iota(v.begin(),v.end(),1); for(int i=0;i<K;i++){int j=(int)(r.uf()*(N-i)); if(j>=N-i) j=N-i-1; swap(v[N-1-i],v[j]);} reverse(v.end()-K,v.end()); return V(v.end()-K,v.end());})
METHOD(floyd_ui, {unordered_set<int>s; V o; for(int j=N-K+1;j<=N;j++){uniform_int_distribution<int>d(1,j); int t=d(r.g); int x=s.count(t)?j:t; s.insert(x); o.push_back(x);} return o;})
METHOD(floyd_mod, {unordered_set<int>s; V o; for(int j=N-K+1;j<=N;j++){int t=1+(r.raw()%j); int x=s.count(t)?j:t; s.insert(x); o.push_back(x);} return o;})
METHOD(floyd_real, {unordered_set<int>s; V o; for(int j=N-K+1;j<=N;j++){int t=1+(int)(r.uf()*j); if(t>j) t=j; int x=s.count(t)?j:t; s.insert(x); o.push_back(x);} return o;})
METHOD(sortkey_raw, {vector<pair<U,int>> a; for(int i=1;i<=N;i++) a.push_back({r.raw(),i}); sort(a.begin(),a.end()); V o; for(int i=0;i<K;i++) o.push_back(a[i].second); return o;})
METHOD(sortkey_real, {vector<pair<double,int>> a; for(int i=1;i<=N;i++) a.push_back({r.uf(),i}); sort(a.begin(),a.end()); V o; for(int i=0;i<K;i++) o.push_back(a[i].second); return o;})
METHOD(sortkey_desc_raw, {vector<pair<U,int>> a; for(int i=1;i<=N;i++) a.push_back({r.raw(),i}); sort(a.rbegin(),a.rend()); V o; for(int i=0;i<K;i++) o.push_back(a[i].second); return o;})
METHOD(sortkey_desc_real, {vector<pair<double,int>> a; for(int i=1;i<=N;i++) a.push_back({r.uf(),i}); sort(a.rbegin(),a.rend()); V o; for(int i=0;i<K;i++) o.push_back(a[i].second); return o;})

